export const TRIGRAM_SCORES: Uint8Array = (() => {
  const binary = atob(DATA);
  const scores = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    scores[index] = binary.charCodeAt(index);
  }
  return scores;
})();
